INSERT INTO units (item_type_id, name, order_index) VALUES ('reading', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('reading', '{"text": "The ostensible rationale for the policy belies a far more pragmatic, if less flattering, set of political considerations."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('reading', '{"text": "One might be forgiven for assuming consensus had been reached, were it not for the dissenting footnote buried in the appendix."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('reading', '{"text": "The committee''s studied ambiguity on the matter speaks less to indecision than to a calculated unwillingness to commit prematurely."}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('reading', '{"text": "Far from allaying concerns, the statement''s carefully hedged language only served to deepen the prevailing sense of unease."}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('reading', '{"text": "It would be disingenuous to attribute the outcome solely to misfortune when the warning signs had been so conspicuously ignored."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('reading', '{"text": "The firm''s belated contrition, however sincere, does little to mitigate the reputational damage already sustained."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('reading', '{"text": "What passes for prudence in boardrooms is, on closer inspection, often little more than institutionalized risk aversion."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('reading', '{"text": "The report''s veneer of objectivity scarcely conceals the ideological commitments animating its central recommendations."}', 0.87, 'C2', 'approved', 'manual', 'education', 'practice', :'s2_id', 3),
('reading', '{"text": "To characterize the settlement as a victory for either side would be to overlook the considerable concessions both ultimately made."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('reading', '{"text": "The policy''s architects seem not to have anticipated how readily its safeguards could be circumvented in practice."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('reading', '{"text": "That the board reached its decision unanimously says rather more about groupthink than it does about the merits of the proposal."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('reading', '{"text": "The firm''s public contrition notwithstanding, insiders suggest the underlying culture remains stubbornly unreformed."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('reading', '{"text": "It is a measure of how normalized the practice had become that its eventual exposure provoked more resignation than outrage."}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('reading', '{"text": "The dissenting opinion, though ultimately unpersuasive to the majority, articulated concerns that subsequent events would largely vindicate."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('reading', '{"text": "Whatever the merits of the policy in the abstract, its implementation was undermined from the outset by institutional inertia."}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('reading_selective', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('reading_selective', '{"text": "The clause''s studied vagueness, far from an oversight, was in fact the product of deliberate negotiation between counsel for both sides.", "question": "Was the clause''s vagueness an oversight?"}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "it was deliberate"]}', :'s1_id', 1),
('reading_selective', '{"text": "Notwithstanding the tribunal''s finding of liability, the damages awarded were, by any reasonable measure, nominal.", "question": "Were the damages substantial?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "they were nominal"]}', :'s1_id', 2),
('reading_selective', '{"text": "The report''s equivocation on the matter of causation has left the question of liability, in practical terms, unresolved.", "question": "Has the question of liability been resolved?"}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "it remains unresolved"]}', :'s1_id', 3),
('reading_selective', '{"text": "The firm''s belated compliance, prompted as it was by regulatory pressure rather than conviction, drew little sympathy from critics.", "question": "What prompted the firm''s compliance?"}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["regulatory pressure", "pressure from regulators"]}', :'s1_id', 4),
('reading_selective', '{"text": "The dissent, though procedurally correct, was substantively overshadowed by the majority''s far more consequential ruling.", "question": "Was the dissent procedurally correct?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["yes"]}', :'s1_id', 5),
('reading_selective', '{"text": "The settlement''s confidentiality provisions, while standard in such disputes, have fueled speculation about what precisely was conceded.", "question": "What has fueled speculation?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["the confidentiality provisions", "the confidentiality clauses"]}', :'s2_id', 1),
('reading_selective', '{"text": "The regulator''s reluctance to pursue criminal charges, notwithstanding the severity of the findings, has drawn pointed criticism.", "question": "Did the regulator pursue criminal charges?"}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "they were reluctant to"]}', :'s2_id', 2),
('reading_selective', '{"text": "The board''s insistence on retaining the executive, despite mounting evidence against him, was widely construed as institutional self-protection.", "question": "How was the board''s insistence construed?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["as self-protection", "institutional self-protection"]}', :'s2_id', 3),
('reading_selective', '{"text": "That the inquiry took three years to conclude speaks as much to institutional obstruction as to the complexity of the case.", "question": "What does the inquiry''s length suggest besides complexity?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["institutional obstruction", "obstruction"]}', :'s2_id', 4),
('reading_selective', '{"text": "The firm''s public apology, issued only after sustained media pressure, was met with widespread skepticism regarding its sincerity.", "question": "Why was the apology issued?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["sustained media pressure", "pressure from the media"]}', :'s2_id', 5),
('reading_selective', '{"text": "The ruling''s narrow scope leaves the broader question of regulatory jurisdiction conspicuously unaddressed.", "question": "Does the ruling address the broader jurisdiction question?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "it leaves it unaddressed"]}', :'s3_id', 1),
('reading_selective', '{"text": "The company''s reluctance to disclose the terms, ostensibly for competitive reasons, has only amplified suspicions of wrongdoing.", "question": "What has the reluctance to disclose amplified?"}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["suspicions of wrongdoing", "suspicion"]}', :'s3_id', 2),
('reading_selective', '{"text": "The dissenting judge''s warnings, dismissed at the time as alarmist, now read as remarkably prescient.", "question": "How were the warnings regarded at the time?"}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["as alarmist", "dismissed as alarmist"]}', :'s3_id', 3),
('reading_selective', '{"text": "The agency''s belated acknowledgment of the flaw does little to redress the harm already inflicted on affected parties.", "question": "Does the acknowledgment redress the harm?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "it does little"]}', :'s3_id', 4),
('reading_selective', '{"text": "The firm''s insistence on its own innocence rings increasingly hollow against the weight of accumulating evidence.", "question": "How does the firm''s insistence on innocence come across?"}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["hollow", "increasingly hollow"]}', :'s3_id', 5);
