INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('short_answer', '{"question": "To what extent can institutional contrition ever genuinely substitute for structural reform?"}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('short_answer', '{"question": "Why might a dissenting opinion prove more consequential in retrospect than the majority ruling it opposed?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('short_answer', '{"question": "What does the persistence of groupthink reveal about the limits of collective decision-making?"}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('short_answer', '{"question": "Why does belated compliance often fail to restore institutional credibility?"}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('short_answer', '{"question": "What distinguishes genuine accountability from its mere performance?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('short_answer', '{"question": "Why might calculated ambiguity sometimes serve an organization better than premature clarity?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('short_answer', '{"question": "What explains the tendency of institutions to normalize practices that would otherwise provoke outrage?"}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('short_answer', '{"question": "Why do safeguards so often fail precisely at the point they are most needed?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('short_answer', '{"question": "What is lost when a settlement prioritizes expedience over a full public reckoning?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('short_answer', '{"question": "Why might regulatory bodies be reluctant to pursue charges even amid damning findings?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('short_answer', '{"question": "To what degree can an institution''s culture be meaningfully reformed without a change in its incentive structures?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('short_answer', '{"question": "What does the public''s resigned, rather than outraged, reaction to scandal suggest about shifting norms?"}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('short_answer', '{"question": "Why might vindication for a dissenting view arrive too late to be of any practical consequence?"}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('short_answer', '{"question": "What role does institutional inertia play in undermining otherwise sound policy?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('short_answer', '{"question": "Why does the appearance of due process sometimes matter more to institutions than its substance?"}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
