INSERT INTO units (item_type_id, name, order_index) VALUES ('conversations', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('conversations', '{"dialogue": "A: The tribunal''s ruling was narrower than expected. B: In what sense? A: It sidestepped the broader jurisdictional question entirely.", "question": "What did the ruling sidestep?"}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["the broader jurisdictional question", "the jurisdiction issue"]}', :'s1_id', 1),
('conversations', '{"dialogue": "A: Their apology felt rather hollow. B: Why do you say that? A: It came only after the story broke publicly.", "question": "Why did the apology feel hollow?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["it came only after the story broke", "it was prompted by publicity"]}', :'s1_id', 2),
('conversations', '{"dialogue": "A: The dissent is being revisited now. B: After all this time? A: Yes, events have largely vindicated it.", "question": "Why is the dissent being revisited?"}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["events vindicated it", "it was proven right"]}', :'s1_id', 3),
('conversations', '{"dialogue": "A: The settlement''s terms remain confidential. B: Does that trouble you? A: It fuels speculation more than it reassures anyone.", "question": "What does the confidentiality do, according to speaker A?"}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["fuels speculation", "it causes speculation"]}', :'s1_id', 4),
('conversations', '{"dialogue": "A: The inquiry took three years. B: Was that justified? A: Partly, though institutional obstruction played a role too.", "question": "What else contributed to the delay besides complexity?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["institutional obstruction", "obstruction"]}', :'s1_id', 5),
('conversations', '{"dialogue": "A: The regulator declined to pursue charges. B: Despite the findings? A: Yes, which has drawn considerable criticism.", "question": "What has drawn criticism?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["declining to pursue charges", "not pursuing charges"]}', :'s2_id', 1),
('conversations', '{"dialogue": "A: The board retained the executive. B: Despite the allegations? A: Precisely, and many saw it as self-protection.", "question": "How was the board''s decision widely interpreted?"}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["as self-protection", "institutional self-protection"]}', :'s2_id', 2),
('conversations', '{"dialogue": "A: The whistleblower''s claims proved accurate. B: All of them? A: Nearly, which has only deepened the fallout.", "question": "What has the accuracy of the claims done?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["deepened the fallout", "made it worse"]}', :'s2_id', 3),
('conversations', '{"dialogue": "A: Their statement was carefully hedged. B: To what effect? A: It deepened unease rather than resolving it.", "question": "What effect did the hedged statement have?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["deepened unease", "made people more worried"]}', :'s2_id', 4),
('conversations', '{"dialogue": "A: The firm''s culture remains unreformed. B: Despite the public apology? A: Precisely, according to several insiders.", "question": "According to insiders, what remains unreformed?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["the firm''s culture", "company culture"]}', :'s2_id', 5),
('conversations', '{"dialogue": "A: Few took the report seriously. B: Why not? A: Its underlying assumptions were thoroughly discredited.", "question": "Why did few take the report seriously?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["its assumptions were discredited", "discredited assumptions"]}', :'s3_id', 1),
('conversations', '{"dialogue": "A: The scandal might have been avoided. B: How so? A: Had the regulator acted more decisively early on.", "question": "What might have avoided the scandal?"}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["decisive early action by the regulator", "earlier regulatory action"]}', :'s3_id', 2),
('conversations', '{"dialogue": "A: The public reaction was surprisingly muted. B: Given the severity? A: Yes, more resignation than outrage, it seems.", "question": "How did the public react?"}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["with resignation rather than outrage", "muted, resigned"]}', :'s3_id', 3),
