INSERT INTO units (item_type_id, name, order_index) VALUES ('dictation', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('dictation', '{"text": "The ruling sidestepped the broader jurisdictional question entirely."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('dictation', '{"text": "Their apology felt hollow since it came only after exposure."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('dictation', '{"text": "The dissent is being revisited now that events have vindicated it."}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('dictation', '{"text": "The settlement''s confidentiality fuels speculation rather than reassurance."}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('dictation', '{"text": "Institutional obstruction contributed to the inquiry''s lengthy delay."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('dictation', '{"text": "The regulator''s reluctance to pursue charges drew considerable criticism."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('dictation', '{"text": "Retaining the executive was widely seen as institutional self-protection."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('dictation', '{"text": "The whistleblower''s claims proved accurate, deepening the fallout considerably."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('dictation', '{"text": "The hedged statement deepened unease rather than resolving it."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('dictation', '{"text": "Insiders suggest the firm''s culture remains stubbornly unreformed."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('dictation', '{"text": "Few took the report seriously once its assumptions were discredited."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('dictation', '{"text": "Decisive early action might well have averted the entire scandal."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('dictation', '{"text": "The public reaction was muted, more resignation than outrage."}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('dictation', '{"text": "The majority opinion was quietly abandoned once the dissent was vindicated."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('dictation', '{"text": "Institutional inertia ensured even sweeping reforms produced little change."}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('passage_reconstruction', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('passage_reconstruction', '{"passage": "The tribunal''s ruling, while procedurally unimpeachable, conspicuously avoided the broader jurisdictional question that had animated much of the proceedings, leaving the matter effectively unresolved for future litigants."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the ruling was procedurally sound", "it avoided the broader jurisdictional question", "the matter remains unresolved for future cases"]}', :'s1_id', 1),
('passage_reconstruction', '{"passage": "What the firm characterized as a routine restructuring was, insiders suggest, a calculated attempt to quietly shed the very executives whose decisions had precipitated the crisis in the first place."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the firm called it routine restructuring", "insiders say it was calculated", "it aimed to remove executives responsible for the crisis"]}', :'s1_id', 2),
('passage_reconstruction', '{"passage": "The regulator''s decision not to pursue criminal charges, despite findings that many considered damning, has been read by critics less as prosecutorial restraint than as institutional deference to powerful interests."}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the regulator declined to pursue charges", "the findings were seen as damning", "critics see this as deference to powerful interests"]}', :'s1_id', 3),
('passage_reconstruction', '{"passage": "The settlement, though framed publicly as a mutual resolution, in fact reflected the plaintiff''s diminishing appetite for protracted litigation rather than any genuine convergence of views between the parties."}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the settlement was framed as mutual", "it actually reflected the plaintiff''s fatigue with litigation", "there was no genuine agreement of views"]}', :'s1_id', 4),
('passage_reconstruction', '{"passage": "The dissenting judge''s warnings, dismissed at the time as alarmist and unsupported by the available evidence, have since been substantially vindicated by developments that few anticipated."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the dissenting judge gave warnings", "they were dismissed as alarmist at the time", "subsequent events have largely vindicated them"]}', :'s1_id', 5),
('passage_reconstruction', '{"passage": "The company''s belated and carefully worded apology, issued only after sustained media scrutiny, failed to quell public anger, not least because it conspicuously avoided any direct admission of wrongdoing."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the apology was belated and carefully worded", "it followed sustained media scrutiny", "it avoided admitting wrongdoing and failed to quell anger"]}', :'s2_id', 1),
('passage_reconstruction', '{"passage": "Though the board''s decision to retain the embattled executive was framed as an act of institutional loyalty, many observers interpreted it instead as a tacit acknowledgment that his removal might invite further scrutiny of the board itself."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the board retained an embattled executive", "it was framed as loyalty", "observers saw it as avoiding scrutiny of the board itself"]}', :'s2_id', 2),
('passage_reconstruction', '{"passage": "The whistleblower''s allegations, initially dismissed by the company as unfounded and vindictive, were ultimately substantiated in full by an independent inquiry, prompting a reckoning few within the organization had anticipated."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the company dismissed the allegations as unfounded", "an independent inquiry substantiated them fully", "this prompted an unanticipated reckoning"]}', :'s2_id', 3),
('passage_reconstruction', '{"passage": "The policy''s architects, confident in its theoretical soundness, appear not to have anticipated how comprehensively its safeguards would be circumvented once implementation revealed the gap between design and practice."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the architects were confident in the policy''s soundness", "they did not anticipate how the safeguards would be circumvented", "implementation revealed a gap between design and practice"]}', :'s2_id', 4),
('passage_reconstruction', '{"passage": "The unanimity of the board''s decision, far from reflecting genuine consensus, has since been attributed by several participants to a reluctance to be the lone dissenting voice in a room dominated by a forceful chairperson."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the board''s decision appeared unanimous", "it did not reflect genuine consensus", "participants cite reluctance to dissent against a forceful chairperson"]}', :'s2_id', 5),
('passage_reconstruction', '{"passage": "The report''s veneer of scientific objectivity, upon closer examination, scarcely concealed the ideological commitments of its authors, whose prior public statements had already signaled their preferred conclusions well before the research began."}', 0.89, 'C2', 'approved', 'manual', 'education', 'practice', '{"key_points": ["the report appeared scientifically objective", "it actually reflected the authors'' ideological commitments", "their prior statements had already signaled their conclusions"]}', :'s3_id', 1),
('passage_reconstruction', '{"passage": "What the company publicly described as an unforeseeable market downturn was, according to internal documents later disclosed in litigation, a risk explicitly flagged by its own analysts years earlier and subsequently disregarded by leadership."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the company called it an unforeseeable downturn", "internal documents showed analysts had flagged the risk years earlier", "leadership disregarded the warning"]}', :'s3_id', 2),
('passage_reconstruction', '{"passage": "The muted public reaction to the scandal''s eventual exposure says perhaps more about the public''s eroded expectations of institutional integrity than it does about the severity of the misconduct itself."}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the public reaction to the scandal was muted", "this reflects eroded expectations of institutional integrity", "rather than the actual severity of the misconduct"]}', :'s3_id', 3),
('passage_reconstruction', '{"passage": "The reforms, though sweeping in their stated ambitions, ultimately proved toothless in practice, undone by an institutional inertia so deeply entrenched that even determined leadership struggled to overcome it."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the reforms were ambitious in scope", "they proved toothless in practice", "deeply entrenched institutional inertia undermined them"]}', :'s3_id', 4),
('passage_reconstruction', '{"passage": "The firm''s insistence on its continued innocence, maintained even as additional evidence accumulated against it, has come to be seen by many observers as emblematic of a broader institutional unwillingness to confront uncomfortable truths."}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the firm insisted on its innocence", "it did so despite accumulating evidence", "observers see this as emblematic of institutional denial"]}', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('reading_comprehension', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('reading_comprehension', '{"passage": "Appellate Opinion: The majority''s reasoning, while internally consistent, rests on a premise the dissent persuasively argues was never actually established at trial.", "question": "What does the dissent argue about the majority''s premise?", "options": ["It was well established", "It was never actually established", "It was irrelevant", "It favored the dissent"]}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 1),
('reading_comprehension', '{"passage": "Analyst Commentary: The company''s much-touted efficiency gains owe less to operational innovation than to an accounting reclassification that conveniently flattered the headline figures.", "question": "What do the efficiency gains actually owe to?", "options": ["Operational innovation", "An accounting reclassification", "Reduced staff", "Higher prices"]}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 2),
('reading_comprehension', '{"passage": "Regulatory Finding: The exemption''s drafters likely did not foresee, though critics argue they should have, how readily it would be exploited by precisely the actors it was meant to constrain.", "question": "What do critics argue the drafters should have foreseen?", "options": ["Nothing needed foreseeing", "How the exemption would be exploited", "That no one would use it", "That it would be popular"]}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 3),
('reading_comprehension', '{"passage": "Editorial: To call the settlement a triumph for accountability is to mistake the avoidance of trial for the achievement of justice.", "question": "What is the editorial''s central criticism?", "options": ["The settlement was a triumph", "Avoiding trial is not the same as achieving justice", "There was no settlement", "Justice was fully achieved"]}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 4),
('reading_comprehension', '{"passage": "Audit Letter: The auditors note that the figures, while technically compliant with accounting standards, present a picture of financial health considerably rosier than the underlying cash position would suggest.", "question": "What does the audit letter suggest about the figures?", "options": ["They are fraudulent", "They present a rosier picture than the cash position suggests", "They understate performance", "They are irrelevant"]}', 0.84, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 5),
('reading_comprehension', '{"passage": "Internal Review: The review concedes that while no individual acted with clear malicious intent, the cumulative effect of countless small, self-interested decisions produced an outcome indistinguishable from deliberate fraud.", "question": "What does the review conclude about individual intent?", "options": ["It was clearly malicious", "No individual acted with clear malicious intent", "Fraud was impossible", "Intent was irrelevant to the outcome"]}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 1),
('reading_comprehension', '{"passage": "Legal Memo: Though the contract''s language is, strictly construed, unambiguous, courts have shown a marked willingness to look beyond the text where the result would otherwise be manifestly unjust.", "question": "What have courts shown willingness to do?", "options": ["Ignore the text entirely", "Look beyond the text in cases of manifest injustice", "Always enforce literal text", "Refuse to rule at all"]}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 2),
('reading_comprehension', '{"passage": "Think Tank Brief: The report''s authors, whatever their methodological rigor, cannot entirely escape the charge that their funding sources shaped which questions were deemed worth asking in the first place.", "question": "What charge can the authors not entirely escape?", "options": ["Poor methodology", "Funding sources shaped the research questions", "They had no funding", "The report was too rigorous"]}', 0.86, 'C2', 'approved', 'manual', 'education', 'practice', '{"correctIndex": 1}', :'s2_id', 3),
('reading_comprehension', '{"passage": "Market Analysis: The firm''s valuation presumes a growth trajectory that, on any dispassionate reading of the underlying data, appears considerably more optimistic than the evidence can support.", "question": "What does the analysis suggest about the growth trajectory?", "options": ["It is well supported by evidence", "It is more optimistic than the evidence supports", "It is too conservative", "There is no growth trajectory"]}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 4),
('reading_comprehension', '{"passage": "Commission Report: The commission stops short of alleging deliberate concealment, yet its findings leave little room for an innocent explanation of the repeated, pattern-like omissions.", "question": "What do the findings leave little room for?", "options": ["Alleging concealment directly", "An innocent explanation of the omissions", "Any further investigation", "Criticism of the commission"]}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 5),
('reading_comprehension', '{"passage": "Judicial Dissent: To accept the majority''s logic is, in effect, to render the statute''s central protection illusory for precisely the class of claimants it was enacted to shield.", "question": "What does the dissent say accepting the majority''s logic would do?", "options": ["Strengthen the statute''s protection", "Render the protection illusory for those it was meant to shield", "Have no practical effect", "Benefit the claimants directly"]}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 1),
('reading_comprehension', '{"passage": "Historical Retrospective: What was celebrated at the time as visionary leadership reads, with the benefit of hindsight and subsequent disclosures, considerably more like reckless disregard dressed in the language of boldness.", "question": "How does the leadership read with hindsight?", "options": ["As visionary", "As reckless disregard dressed as boldness", "As entirely justified", "As irrelevant to the outcome"]}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 2),
('reading_comprehension', '{"passage": "Policy Postmortem: The policy''s failure cannot be attributed to any single flaw in its design but rather to the cumulative effect of implementation choices that, individually defensible, collectively hollowed out its intent.", "question": "What caused the policy''s failure?", "options": ["A single design flaw", "The cumulative effect of implementation choices", "Lack of any implementation", "Public opposition alone"]}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 3),
('reading_comprehension', '{"passage": "Academic Review: The study''s most striking contribution may ultimately be remembered less for its conclusions than for the methodological debate it inadvertently provoked within the field.", "question": "What may the study be remembered for?", "options": ["Its conclusions alone", "The methodological debate it provoked", "Being entirely forgotten", "Having no influence on the field"]}', 0.89, 'C2', 'approved', 'manual', 'education', 'practice', '{"correctIndex": 1}', :'s3_id', 4),
('reading_comprehension', '{"passage": "Financial Postmortem: In retrospect, the collapse owed as much to a culture that discouraged dissent as to any single misjudged bet, a distinction the institution has been slow to acknowledge.", "question": "What does the institution acknowledge slowly, according to the passage?", "options": ["That the collapse was due to a single bet", "That a culture discouraging dissent contributed significantly", "That no mistakes were made", "That the collapse was unavoidable"]}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('response_selection', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('response_selection', '{"text": "The dissent has since been largely vindicated by events.", "options": ["Perhaps the majority ought to reconsider its position.", "The cafeteria menu rotates weekly.", "He prefers aisle seats on flights."]}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s1_id', 1),
('response_selection', '{"text": "Our belated apology was met with widespread skepticism.", "options": ["We may need a more substantive gesture than words alone.", "The office relocated last spring.", "She enjoys long-distance running."]}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s1_id', 2),
('response_selection', '{"text": "The settlement''s confidentiality has fueled speculation.", "options": ["We should consider whether that silence serves us well.", "The building has a new security system.", "He collects antique maps."]}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s1_id', 3),
('response_selection', '{"text": "Our report''s objectivity has been publicly questioned.", "options": ["We ought to address the funding concerns directly.", "The parking structure is being repaved.", "She prefers working remotely."]}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s1_id', 4),
('response_selection', '{"text": "Our audit figures look technically compliant but misleading.", "options": ["We should present a fuller picture to the board.", "The elevator was recently inspected.", "He prefers working late at night."]}', 0.84, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s1_id', 5),
('response_selection', '{"text": "The regulator''s restraint has drawn pointed criticism.", "options": ["We should anticipate further scrutiny regardless.", "The lobby was recently redecorated.", "He enjoys sailing on weekends."]}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s2_id', 1),
('response_selection', '{"text": "Retaining the executive was seen as self-protection.", "options": ["Perhaps we underestimated the optics of that decision.", "The cafeteria closes early on Fridays.", "She''s taking up painting lessons."]}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s2_id', 2),
('response_selection', '{"text": "Our competitor is undercutting us on every major contract.", "options": ["We need to reassess our value proposition entirely.", "The lobby plants need replacing.", "He prefers aisle seats on trains."]}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s2_id', 5),
('response_selection', '{"text": "The whistleblower''s claims proved entirely accurate.", "options": ["We owe them a far more serious response than we gave.", "The elevator was serviced yesterday.", "He enjoys collecting vinyl records."]}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s2_id', 3),
('response_selection', '{"text": "Our institutional culture remains stubbornly unreformed.", "options": ["Surface changes clearly haven''t addressed the real issue.", "The cafeteria introduced a new menu.", "She prefers tea to coffee in the mornings."]}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s2_id', 4),
('response_selection', '{"text": "Our growth projections appear overly optimistic to analysts.", "options": ["We should revisit the assumptions underpinning them.", "The office recently installed new lighting.", "He enjoys hiking in the mountains."]}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 1),
('response_selection', '{"text": "The commission stopped short of alleging deliberate concealment.", "options": ["Even so, the pattern leaves little room for innocent explanation.", "The building has excellent natural lighting.", "She''s learning a new language."]}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 2),
('response_selection', '{"text": "The policy''s failure stemmed from cumulative implementation choices.", "options": ["We should examine each decision rather than seek a single culprit.", "The parking garage recently expanded.", "He prefers early morning meetings."]}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 3),
('response_selection', '{"text": "The institution has been slow to acknowledge its culture of silence.", "options": ["That reluctance may itself be part of the problem.", "The lobby renovation finished last month.", "She enjoys classical literature."]}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 4),
('response_selection', '{"text": "Our firm''s insistence on innocence rings increasingly hollow.", "options": ["We should reconsider our public messaging strategy entirely.", "The cafeteria added a salad bar.", "He enjoys weekend cycling trips."]}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 5);
