INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('passage_comprehension', '{"story": "An asset manager had long touted its risk models as industry-leading, yet when the downturn arrived, those models proved to have systematically underestimated tail risk for years, a flaw only apparent in hindsight.", "question": "What had the risk models systematically underestimated?"}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["tail risk", "the risk of extreme events"]}', :'s1_id', 1),
('passage_comprehension', '{"story": "An asset manager had long touted its risk models as industry-leading, yet when the downturn arrived, those models proved to have systematically underestimated tail risk for years, a flaw only apparent in hindsight.", "question": "When did this flaw become apparent?"}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["only in hindsight", "after the downturn"]}', :'s1_id', 2),
('passage_comprehension', '{"story": "An asset manager had long touted its risk models as industry-leading, yet when the downturn arrived, those models proved to have systematically underestimated tail risk for years, a flaw only apparent in hindsight.", "question": "How had the firm described its models previously?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["industry-leading", "as the best in the industry"]}', :'s1_id', 3),
('passage_comprehension', '{"story": "A regulator''s decision to settle rather than prosecute was framed internally as pragmatic, though several departing officials later suggested it reflected a reluctance to confront politically connected defendants.", "question": "How was the decision framed internally?"}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["as pragmatic", "pragmatic"]}', :'s1_id', 4),
('passage_comprehension', '{"story": "A regulator''s decision to settle rather than prosecute was framed internally as pragmatic, though several departing officials later suggested it reflected a reluctance to confront politically connected defendants.", "question": "What did departing officials suggest instead?"}', 0.84, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["reluctance to confront connected defendants", "avoiding politically connected people"]}', :'s1_id', 5),
('passage_comprehension', '{"story": "A university''s flagship research center was quietly defunded after an internal review concluded its headline findings, though widely cited, could not be reliably reproduced by independent teams.", "question": "Why was the research center defunded?"}', 0.85, 'C2', 'approved', 'manual', 'education', 'practice', '{"acceptable_answers": ["findings could not be reproduced", "irreproducible results"]}', :'s2_id', 1),
('passage_comprehension', '{"story": "A university''s flagship research center was quietly defunded after an internal review concluded its headline findings, though widely cited, could not be reliably reproduced by independent teams.", "question": "How were the findings previously regarded?"}', 0.86, 'C2', 'approved', 'manual', 'education', 'practice', '{"acceptable_answers": ["widely cited", "well known and cited"]}', :'s2_id', 2),
('passage_comprehension', '{"story": "A multinational''s much-publicized sustainability pledge turned out, upon independent audit, to rely heavily on carbon offsets of dubious provenance rather than genuine emissions reductions.", "question": "What did the audit reveal about the sustainability pledge?"}', 0.87, 'C2', 'approved', 'manual', 'environment', 'practice', '{"acceptable_answers": ["it relied on dubious carbon offsets", "offsets of questionable quality"]}', :'s2_id', 3),
('passage_comprehension', '{"story": "A multinational''s much-publicized sustainability pledge turned out, upon independent audit, to rely heavily on carbon offsets of dubious provenance rather than genuine emissions reductions.", "question": "What did the pledge not genuinely achieve?"}', 0.86, 'C2', 'approved', 'manual', 'environment', 'practice', '{"acceptable_answers": ["genuine emissions reductions", "real emissions cuts"]}', :'s2_id', 4),
('passage_comprehension', '{"story": "A law firm''s internal investigation into partner misconduct concluded with recommendations so narrowly scoped that critics argued they addressed the symptom rather than the underlying culture that had enabled the behavior.", "question": "What did critics argue about the recommendations?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["they addressed symptoms not the culture", "too narrow in scope"]}', :'s2_id', 5),
('passage_comprehension', '{"story": "A central bank''s decision to raise interest rates sharply, though widely criticized at the time as excessive, is now credited by many economists with averting a far more damaging bout of runaway inflation.", "question": "How was the decision viewed at the time?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["criticized as excessive", "widely criticized"]}', :'s3_id', 1),
('passage_comprehension', '{"story": "A central bank''s decision to raise interest rates sharply, though widely criticized at the time as excessive, is now credited by many economists with averting a far more damaging bout of runaway inflation.", "question": "What do economists now credit the decision with?"}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["averting runaway inflation", "preventing worse inflation"]}', :'s3_id', 2),
('passage_comprehension', '{"story": "A pharmaceutical company''s decision to voluntarily withdraw a profitable drug, upon discovering a rare but serious side effect, was initially criticized by investors but later cited as a textbook case of responsible corporate conduct.", "question": "How did investors initially react to the withdrawal?"}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["they criticized it", "critically"]}', :'s3_id', 3),
('passage_comprehension', '{"story": "A pharmaceutical company''s decision to voluntarily withdraw a profitable drug, upon discovering a rare but serious side effect, was initially criticized by investors but later cited as a textbook case of responsible corporate conduct.", "question": "How was the decision later regarded?"}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["as a textbook case of responsible conduct", "a model of good corporate behavior"]}', :'s3_id', 4),
('passage_comprehension', '{"story": "An airline''s notoriously opaque pricing model, long defended internally as a competitive necessity, was eventually abandoned after consumer-protection litigation made its continuation untenable.", "question": "Why was the pricing model eventually abandoned?"}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["litigation made it untenable", "consumer-protection lawsuits"]}', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('story_retelling', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('story_retelling', '{"story": "A regional bank''s risk committee had, for years, dismissed warnings from its own junior analysts about concentrated exposure to a single volatile sector. When the sector eventually collapsed, the bank''s losses were disproportionately severe, and an internal postmortem concluded that institutional hierarchy, more than any lack of information, had been the decisive failure."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('story_retelling', '{"story": "A prestigious journal retracted a landmark study after a graduate student, attempting to replicate its results for an unrelated project, discovered the original dataset contained statistical anomalies inconsistent with genuine observation. The episode prompted a broader reckoning within the field about the adequacy of peer review as a safeguard against fabrication."}', 0.82, 'C2', 'approved', 'manual', 'education', 'practice', :'s1_id', 2),
('story_retelling', '{"story": "A conglomerate''s decision to divest a chronically underperforming division was initially celebrated by analysts as decisive leadership. Only later did it emerge that the division had been deliberately starved of investment for years specifically to justify its eventual sale, a revelation that cast the earlier praise in a considerably less flattering light."}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('story_retelling', '{"story": "A city''s long-serving ombudsman resigned abruptly after being pressured to soften findings critical of a politically connected developer. The subsequent public outcry over the resignation did more to expose the underlying conflict of interest than the original report itself ever could have."}', 0.81, 'C2', 'approved', 'manual', 'community', 'practice', :'s1_id', 4),
('story_retelling', '{"story": "A technology firm''s internal ethics board had repeatedly flagged a product feature as likely to enable misuse, yet commercial pressures ensured the feature shipped regardless. When the predicted misuse materialized publicly, the firm''s leadership expressed surprise that drew considerable skepticism from employees who recalled the board''s earlier warnings."}', 0.82, 'C2', 'approved', 'manual', 'technology', 'practice', :'s1_id', 5),
('story_retelling', '{"story": "A multinational''s sustainability report claimed substantial progress on emissions reduction, a claim that unraveled once journalists discovered the baseline year used for comparison had been deliberately chosen because it coincided with an unrelated production slowdown, artificially inflating the appearance of improvement."}', 0.85, 'C2', 'approved', 'manual', 'environment', 'practice', :'s2_id', 1),
('story_retelling', '{"story": "A hospital system''s leadership had long resisted calls to overhaul its antiquated scheduling software, citing cost concerns. It took a widely publicized incident, in which the system''s failure contributed directly to a preventable patient harm, before the necessary investment was finally approved."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('story_retelling', '{"story": "An investment bank''s compliance department had drafted increasingly urgent memos about a trading desk''s irregular activity over eighteen months, memos that were consistently deprioritized by senior management preoccupied with the desk''s impressive short-term returns. The eventual scandal, when it broke, surprised almost no one within compliance."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('story_retelling', '{"story": "A government agency''s decision to award a major contract without competitive bidding was defended at the time as an emergency measure necessitated by exceptional circumstances. A subsequent audit found the circumstances cited had, in fact, been known and anticipated for months prior, undermining the agency''s original justification."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('story_retelling', '{"story": "A manufacturing firm''s decision to relocate production overseas was presented publicly as a response to labor costs alone. Internal documents later disclosed in an unrelated lawsuit revealed that avoiding an impending environmental regulation had, in fact, been the primary motivating factor all along."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('story_retelling', '{"story": "A long-respected research institute''s reputation for independence was quietly undermined over years by an increasing reliance on funding from entities with direct financial stakes in the institute''s conclusions, a dependency that institute leadership had consistently and publicly denied until internal documents surfaced proving otherwise."}', 0.89, 'C2', 'approved', 'manual', 'education', 'practice', :'s3_id', 1),
('story_retelling', '{"story": "A national airline''s safety culture had, according to a subsequent inquiry, been gradually eroded by a management philosophy that treated near-miss incidents as evidence of resilience rather than as the warning signs they actually were, a misreading that proved catastrophic once circumstances finally aligned unfavorably."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('story_retelling', '{"story": "A software company''s widely praised user-growth metrics were later found to have included a substantial proportion of automated, non-human accounts, a fact the company''s own data team had identified internally but chosen not to disclose, reportedly for fear of undermining investor confidence ahead of a funding round."}', 0.91, 'C2', 'approved', 'manual', 'technology', 'practice', :'s3_id', 3),
('story_retelling', '{"story": "A judicial inquiry into a wrongful conviction found that the original investigators had not acted with deliberate malice, but rather with a cumulative series of small confirmation biases that, left unchecked by institutional safeguards, produced an outcome functionally indistinguishable from intentional misconduct."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('story_retelling', '{"story": "A century-old family business, having survived numerous economic downturns through sheer conservatism, nearly collapsed when a fifth-generation leader''s attempt at rapid modernization outpaced the organization''s institutional capacity to adapt, a failure that ultimately vindicated the very caution his predecessors had been criticized for."}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('speaking_situations', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('speaking_situations', '{"situation": "You must testify before a committee about an institutional failure you personally warned against. What would you say?"}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('speaking_situations', '{"situation": "A journalist confronts you with evidence that contradicts your organization''s public statements. What would you say?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('speaking_situations', '{"situation": "You must explain to a board why you believe a popular, profitable practice should nonetheless be discontinued on ethical grounds. What would you say?"}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('speaking_situations', '{"situation": "A respected mentor asks you to overlook a serious compliance issue for the sake of a relationship. What would you say?"}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('speaking_situations', '{"situation": "You must deliver a eulogy-like assessment of a failed initiative you once championed. What would you say?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('speaking_situations', '{"situation": "You need to persuade skeptical colleagues that an unpopular but necessary institutional reckoning cannot be delayed further. What would you say?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('speaking_situations', '{"situation": "You must respond, live on air, to an accusation that your organization has been complicit in long-term harm. What would you say?"}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('speaking_situations', '{"situation": "A former colleague asks you to corroborate a version of events you know to be incomplete. What would you say?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('speaking_situations', '{"situation": "You must explain to shareholders why the company is voluntarily disclosing a failure before being legally compelled to. What would you say?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('speaking_situations', '{"situation": "You need to address an audience that largely believes an institution you represent is beyond reform. What would you say?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('speaking_situations', '{"situation": "You must argue, before a skeptical tribunal, that a decision widely condemned at the time was in fact the correct one. What would you say?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('speaking_situations', '{"situation": "You need to tell a founder that the culture they built, however successful commercially, must now be fundamentally dismantled. What would you say?"}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('speaking_situations', '{"situation": "You must explain to an incoming successor the institutional dysfunctions they will inherit, without appearing to disown your own role in them. What would you say?"}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('speaking_situations', '{"situation": "You need to respond to a whistleblower who believes, not unreasonably, that your prior assurances to them were insincere. What would you say?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('speaking_situations', '{"situation": "You must deliver remarks marking an institution''s anniversary while candidly acknowledging its most serious historical failures. What would you say?"}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('open_questions', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('open_questions', '{"prompt": "Can an institution ever be said to have genuinely reformed if the individuals responsible for its past failures remain in positions of influence?"}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('open_questions', '{"prompt": "Is moral culpability diminished when harm results from the aggregation of many small, individually defensible decisions rather than a single deliberate act?"}', 0.82, 'C2', 'approved', 'manual', 'general', 'practice', :'s1_id', 2),
('open_questions', '{"prompt": "To what extent should institutions be judged by the outcomes of their decisions versus the soundness of their reasoning at the time?"}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('open_questions', '{"prompt": "Does the public''s growing cynicism toward institutional apologies ultimately serve, or undermine, genuine accountability?"}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('open_questions', '{"prompt": "Can a culture of institutional loyalty be reconciled with an obligation to disclose uncomfortable truths?"}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('open_questions', '{"prompt": "Is it possible to meaningfully regulate against failures of judgment, as opposed to failures of process?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('open_questions', '{"prompt": "Should historical vindication of a dissenting view carry any formal weight in how we evaluate the original decision-makers?"}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('open_questions', '{"prompt": "What obligations, if any, do institutions have to the public once a settlement has legally resolved but not publicly explained a controversy?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('open_questions', '{"prompt": "Can transparency become a substitute for accountability rather than a mechanism for achieving it?"}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('open_questions', '{"prompt": "Is institutional inertia best understood as a failure of leadership, or as an inevitable feature of any sufficiently complex organization?"}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('open_questions', '{"prompt": "Does society''s tendency toward resignation, rather than outrage, in the face of repeated institutional failure reflect wisdom or complacency?"}', 0.89, 'C2', 'approved', 'manual', 'general', 'practice', :'s3_id', 1),
('open_questions', '{"prompt": "Should individuals who benefited unknowingly from institutional wrongdoing bear any responsibility for its redress?"}', 0.90, 'C2', 'approved', 'manual', 'general', 'practice', :'s3_id', 2),
('open_questions', '{"prompt": "Can an organization''s stated values ever be meaningfully distinguished from the incentives that actually govern its behavior?"}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('open_questions', '{"prompt": "Is there a meaningful difference between an institution that conceals its failures and one that simply never adequately examines them?"}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('open_questions', '{"prompt": "What does it say about an institution if genuine reform only becomes possible after a change in leadership, rather than through internal will?"}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
