INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('email_writing', '{"prompt": "Write an email to the board arguing that a popular, profitable practice should be discontinued on ethical grounds, anticipating and addressing likely objections."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('email_writing', '{"prompt": "Write an email to a regulator proactively disclosing a failure your organization has not yet been legally compelled to reveal."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('email_writing', '{"prompt": "Write an email to shareholders explaining why a decision widely criticized at the time should now be understood as having been correct."}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('email_writing', '{"prompt": "Write an email to a successor candidly outlining the institutional dysfunctions they will inherit without appearing to disown your own role in them."}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('email_writing', '{"prompt": "Write an email responding to a whistleblower who reasonably believes your organization''s prior assurances to them were insincere."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('email_writing', '{"prompt": "Write an email to employees acknowledging that a culture of institutional loyalty had suppressed necessary internal dissent."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('email_writing', '{"prompt": "Write an email to an incoming regulator proposing a framework for addressing failures of judgment rather than merely failures of process."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('email_writing', '{"prompt": "Write an email to the public explaining why a settlement, though legally resolving a controversy, does not constitute a full public accounting of it."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('email_writing', '{"prompt": "Write an email to the board recommending against retaining a senior executive despite the reputational cost of their departure."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('email_writing', '{"prompt": "Write an email to investors explaining why the company''s prior growth metrics should be understood as having been materially misleading."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('email_writing', '{"prompt": "Write an email marking an institution''s anniversary that candidly acknowledges its most serious historical failures without undermining institutional morale."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('email_writing', '{"prompt": "Write an email to a journalist responding to an accusation of long-term institutional complicity, neither admitting nor denying more than is accurate."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('email_writing', '{"prompt": "Write an email to the board arguing that institutional inertia, not any single decision, was the true cause of a major failure."}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('email_writing', '{"prompt": "Write an email to a founder explaining why the culture they built, however commercially successful, must now be fundamentally dismantled."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('email_writing', '{"prompt": "Write an email to stakeholders distinguishing between the company''s stated values and the incentives that have actually governed its behavior, and proposing how to close that gap."}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
