INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('summary_and_opinion', '{"passage": "A growing body of legal scholarship questions whether corporate personhood, once a narrow legal fiction, has expanded well beyond its original purpose. Proponents of reform argue this expansion has shielded individuals from accountability, while defenders maintain it remains essential to commercial predictability."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["corporate personhood has expanded beyond its original purpose", "reformers say it shields individuals from accountability", "defenders say it remains essential for commercial predictability"]}', :'s1_id', 1),
('summary_and_opinion', '{"passage": "Some economists argue that central banks'' independence, long considered sacrosanct, has in practice insulated monetary policy from the democratic accountability that governs nearly every other lever of state power. Others counter that this very insulation is precisely what prevents short-term political pressures from undermining long-term economic stability."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["central bank independence insulates policy from accountability", "critics see this as a democratic deficit", "defenders say insulation protects long-term stability"]}', :'s1_id', 2),
('summary_and_opinion', '{"passage": "A contentious debate persists over whether algorithmic content moderation, for all its scalability, has effectively outsourced decisions of genuine civic consequence to systems whose underlying logic remains largely opaque even to their own creators."}', 0.83, 'C2', 'approved', 'manual', 'technology', 'practice', '{"key_points": ["algorithmic moderation is scalable", "it outsources civically consequential decisions", "the logic remains opaque even to creators"]}', :'s1_id', 3),
('summary_and_opinion', '{"passage": "Critics of modern philanthropy argue that large-scale charitable giving by the ultra-wealthy, however well-intentioned, allows a small number of individuals to exercise disproportionate influence over public priorities that would otherwise be determined democratically."}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["large-scale philanthropy is well-intentioned", "critics say it gives disproportionate influence to a few", "it shapes priorities otherwise determined democratically"]}', :'s1_id', 4),
('summary_and_opinion', '{"passage": "Some scholars contend that the proliferation of non-disclosure agreements in employment settings has quietly institutionalized a culture of silence that extends well beyond its stated purpose of protecting legitimate trade secrets."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["NDAs have proliferated in employment", "they institutionalize a culture of silence", "this extends beyond protecting legitimate trade secrets"]}', :'s1_id', 5),
('summary_and_opinion', '{"passage": "A debate has intensified over whether shareholder primacy, long the dominant organizing principle of corporate governance, remains defensible in an era when corporate decisions increasingly bear on matters of genuine public consequence, from climate to public health."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["shareholder primacy has long dominated governance", "corporate decisions now bear on public consequence", "its continued defensibility is being questioned"]}', :'s2_id', 1),
('summary_and_opinion', '{"passage": "Some argue that the increasing financialization of housing markets has transformed shelter from a fundamental need into a speculative asset class, with consequences for affordability that policymakers have been slow to meaningfully address."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["housing has become financialized", "shelter is treated as a speculative asset", "policymakers have been slow to address affordability"]}', :'s2_id', 2),
('summary_and_opinion', '{"passage": "A persistent tension exists between the ideal of a free press holding institutions accountable and the commercial pressures that increasingly shape which stories receive sustained investigative attention and which quietly fade from view."}', 0.87, 'C2', 'approved', 'manual', 'culture', 'practice', '{"key_points": ["a free press is meant to hold institutions accountable", "commercial pressures shape coverage", "some stories receive attention while others fade"]}', :'s2_id', 3),
('summary_and_opinion', '{"passage": "Critics of modern credentialism argue that the increasing reliance on formal qualifications, rather than demonstrated competence, has created artificial barriers to opportunity that disproportionately affect those without access to elite institutions."}', 0.85, 'C2', 'approved', 'manual', 'education', 'practice', '{"key_points": ["credentialism relies on formal qualifications over competence", "critics say it creates artificial barriers", "it disproportionately affects those without elite access"]}', :'s2_id', 4),
('summary_and_opinion', '{"passage": "Some legal theorists question whether the doctrine of limited liability, foundational to modern capitalism, adequately accounts for harms whose true costs are externalized onto third parties who had no voice in the original transaction."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["limited liability is foundational to capitalism", "theorists question whether it accounts for externalized harms", "affected third parties had no voice in the transaction"]}', :'s2_id', 5),
('summary_and_opinion', '{"passage": "A growing contingent of scholars argue that the entire framework of quarterly earnings reporting has distorted corporate decision-making toward short-termism in ways that are only now being fully reckoned with, decades after the practice became standard."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["quarterly earnings reporting became standard decades ago", "scholars say it distorted decisions toward short-termism", "the full consequences are only now being reckoned with"]}', :'s3_id', 1),
('summary_and_opinion', '{"passage": "Some argue that the revolving door between regulators and the industries they oversee has become so normalized that its corrosive effect on genuine oversight is rarely even remarked upon, let alone seriously addressed."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["a revolving door exists between regulators and industry", "this has become normalized", "its corrosive effect on oversight goes largely unaddressed"]}', :'s3_id', 2),
('summary_and_opinion', '{"passage": "A contentious strand of legal philosophy holds that corporate criminal liability, as currently structured, allows institutions to absorb the costs of wrongdoing as a mere operating expense, insulating the individuals actually responsible from any genuine personal consequence."}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["corporate criminal liability is currently structured a certain way", "it lets institutions treat wrongdoing costs as an operating expense", "individuals responsible avoid genuine personal consequence"]}', :'s3_id', 3),
('summary_and_opinion', '{"passage": "Some economists contend that the pursuit of frictionless global supply chains, long celebrated for its efficiency, has left economies dangerously exposed to disruptions whose systemic risks were, in retrospect, both foreseeable and largely ignored."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["frictionless supply chains were celebrated for efficiency", "this left economies exposed to disruption", "the systemic risks were foreseeable but largely ignored"]}', :'s3_id', 4),
('summary_and_opinion', '{"passage": "A minority but growing view among historians holds that institutions are rarely reformed from within by genuine moral reckoning, but almost always by external pressure that makes the costs of inaction suddenly and unavoidably exceed the costs of change."}', 0.92, 'C2', 'approved', 'manual', 'general', 'practice', '{"key_points": ["this view holds institutions are rarely reformed from within", "reform usually comes from external pressure", "it happens when the cost of inaction exceeds the cost of change"]}', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('typing', 'C2 - Proficient', 6) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('typing', '{"text": "The ostensible rationale for the policy belies a far more pragmatic, if considerably less flattering, set of underlying political considerations."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('typing', '{"text": "One might be forgiven for assuming genuine consensus had been reached, were it not for the dissenting footnote quietly buried in the appendix."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('typing', '{"text": "The committee''s studied ambiguity on the matter speaks less to indecision than to a calculated unwillingness to commit prematurely."}', 0.83, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('typing', '{"text": "Far from allaying concerns, the statement''s carefully hedged language only served to deepen the prevailing sense of institutional unease."}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('typing', '{"text": "It would be disingenuous to attribute the outcome solely to misfortune when the warning signs had been so conspicuously disregarded."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('typing', '{"text": "The firm''s belated contrition, however sincere it may genuinely be, does little to mitigate the reputational damage already sustained."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('typing', '{"text": "What passes for prudence in most boardrooms is, on closer inspection, often little more than deeply institutionalized risk aversion."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('typing', '{"text": "The report''s veneer of scholarly objectivity scarcely conceals the ideological commitments quietly animating its central recommendations."}', 0.87, 'C2', 'approved', 'manual', 'education', 'practice', :'s2_id', 3),
('typing', '{"text": "To characterize the eventual settlement as a clear victory for either side overlooks the considerable concessions both parties ultimately made."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('typing', '{"text": "The policy''s original architects seem not to have fully anticipated how readily its safeguards could later be circumvented in practice."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('typing', '{"text": "That the board reached its decision entirely unanimously says rather more about groupthink than it does about the proposal''s actual merits."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('typing', '{"text": "The firm''s public contrition notwithstanding, several insiders suggest the underlying institutional culture remains stubbornly unreformed."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('typing', '{"text": "It is a measure of how thoroughly normalized the practice had become that its eventual exposure provoked more resignation than outrage."}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('typing', '{"text": "The dissenting opinion, though ultimately unpersuasive to the majority at the time, articulated concerns later events would largely vindicate."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('typing', '{"text": "Whatever the merits of the policy in the abstract, its implementation was undermined from the very outset by sheer institutional inertia."}', 0.92, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
