('free_writing', '{"prompt": "Write a paragraph examining whether corporate personhood has expanded well beyond any principled justification for its original purpose."}', 0.80, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('free_writing', '{"prompt": "Write a paragraph arguing whether central bank independence represents a democratic deficit or a necessary safeguard."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('free_writing', '{"prompt": "Write a paragraph discussing whether algorithmic content moderation has outsourced civic decisions to systems whose logic remains opaque."}', 0.83, 'C2', 'approved', 'manual', 'technology', 'practice', :'s1_id', 3),
('free_writing', '{"prompt": "Write a paragraph examining whether large-scale private philanthropy undermines or complements democratic decision-making."}', 0.81, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('free_writing', '{"prompt": "Write a paragraph arguing whether non-disclosure agreements in employment have institutionalized a culture of silence beyond their stated purpose."}', 0.82, 'C2', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('free_writing', '{"prompt": "Write a paragraph discussing whether shareholder primacy remains defensible given the public consequences of modern corporate decisions."}', 0.85, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('free_writing', '{"prompt": "Write a paragraph examining whether the financialization of housing has fundamentally undermined its role as a basic human need."}', 0.86, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('free_writing', '{"prompt": "Write a paragraph arguing whether commercial pressures on journalism have compromised its role in holding institutions accountable."}', 0.87, 'C2', 'approved', 'manual', 'culture', 'practice', :'s2_id', 3),
('free_writing', '{"prompt": "Write a paragraph discussing whether credentialism creates artificial barriers that disproportionately disadvantage those without elite access."}', 0.85, 'C2', 'approved', 'manual', 'education', 'practice', :'s2_id', 4),
('free_writing', '{"prompt": "Write a paragraph examining whether limited liability adequately accounts for harms externalized onto uninvolved third parties."}', 0.87, 'C2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('free_writing', '{"prompt": "Write a paragraph arguing whether quarterly earnings reporting has structurally distorted corporate decision-making toward short-termism."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('free_writing', '{"prompt": "Write a paragraph discussing whether the revolving door between regulators and industry has normalized a corrosive conflict of interest."}', 0.90, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('free_writing', '{"prompt": "Write a paragraph examining whether corporate criminal liability allows institutions to treat wrongdoing as a mere operating expense."}', 0.91, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('free_writing', '{"prompt": "Write a paragraph arguing whether the pursuit of efficient global supply chains has left economies dangerously exposed to foreseeable disruption."}', 0.89, 'C2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('free_writing', '{"prompt": "Write a paragraph discussing whether institutions can ever genuinely reform from within, absent external pressure that makes the cost of inaction exceed the cost of change."}', 0.92, 'C2', 'approved', 'manual', 'general', 'practice', :'s3_id', 5);
